package exercise
import("io";"context";"compress/gzip";"bufio";"errors";"fmt")
var ErrLimit=errors.New("resource limit exceeded")
type budgetReader struct{reader io.Reader;ctx context.Context;used,limit int64;label string}
func(b *budgetReader)Read(p []byte)(int,error){
 if err:=b.ctx.Err();err!=nil{return 0,err}
 remaining:=b.limit-b.used
 if int64(len(p))>remaining+1{p=p[:int(remaining+1)]}
 n,err:=b.reader.Read(p);b.used+=int64(n)
 if b.used>b.limit{return 0,fmt.Errorf("%w: %s",ErrLimit,b.label)}
 return n,err
}
func ParseGzip(ctx context.Context,src io.Reader,maxCompressed,maxExpanded int64,maxRecord,maxRecords int)([][]byte,error){
 if ctx==nil||src==nil||maxCompressed<1||maxCompressed>1048576||maxExpanded<1||maxExpanded>4194304||maxRecord<1||maxRecord>1048576||maxRecords<1||maxRecords>10000{return nil,errors.New("invalid bounded input")}
 if err:=ctx.Err();err!=nil{return nil,err}
 compressed:=&budgetReader{reader:src,ctx:ctx,limit:maxCompressed,label:"compressed bytes"}
 archive,err:=gzip.NewReader(compressed);if err!=nil{return nil,err};defer archive.Close()
 expanded:=&budgetReader{reader:archive,ctx:ctx,limit:maxExpanded,label:"expanded bytes"}
 scanner:=bufio.NewScanner(expanded);capacity:=maxRecord+3;if capacity>4096{capacity=4096}
 scanner.Buffer(make([]byte,0,capacity),maxRecord+3)
 var result [][]byte
 for scanner.Scan(){
  if err:=ctx.Err();err!=nil{return nil,err}
  if len(scanner.Bytes())>maxRecord||len(result)>=maxRecords{return nil,fmt.Errorf("%w: record budget",ErrLimit)}
  row:=make([]byte,len(scanner.Bytes()));copy(row,scanner.Bytes());result=append(result,row)
 }
 if err:=scanner.Err();err!=nil{if errors.Is(err,bufio.ErrTooLong){return nil,fmt.Errorf("%w: record bytes",ErrLimit)};return nil,err}
 if err:=ctx.Err();err!=nil{return nil,err}
 return result,nil
}
```

原题知识说明：
分别限制上传字节、解压后字节、记录长度、记录数和处理时间，逐条流式解析并支持取消。仅限制压缩输入不能阻止解压炸弹，单次ReadAll会放大内存风险。超限必须明确失败并避免发布部分完整假象。

