package exercise
import("testing";"bytes";"compress/gzip";"context";"errors";"io";"reflect";"strings")
func packed(raw string)[]byte{var output bytes.Buffer;w:=gzip.NewWriter(&output);_,_ =w.Write([]byte(raw));_ =w.Close();return output.Bytes()}
func TestIndependentBudgets(t *testing.T){
 raw:="alpha\nbeta\nlast";data:=packed(raw);ctx:=context.Background()
 rows,err:=ParseGzip(ctx,bytes.NewReader(data),int64(len(data)),int64(len(raw)),5,3)
 if err!=nil||!reflect.DeepEqual(rows,[][]byte{[]byte("alpha"),[]byte("beta"),[]byte("last")}){t.Fatal("exact budgets",rows,err)}
 limits:=[]struct{compressed,expanded int64;record,count int}{
  {int64(len(data)-1),int64(len(raw)),5,3}, {int64(len(data)),int64(len(raw)-1),5,3},
  {int64(len(data)),int64(len(raw)),4,3},{int64(len(data)),int64(len(raw)),5,2},
 }
 for _,limit:=range limits{rows,err:=ParseGzip(ctx,bytes.NewReader(data),limit.compressed,limit.expanded,limit.record,limit.count);if !errors.Is(err,ErrLimit)||rows!=nil{t.Fatal("budget bypass or partial success",limit,rows,err)}}
 highRatio:=packed(strings.Repeat("x",200*1024)+"\n");if len(highRatio)>1024{t.Fatal("fixture ratio")}
 rows,err=ParseGzip(ctx,bytes.NewReader(highRatio),1024,1024,300000,10);if !errors.Is(err,ErrLimit)||rows!=nil{t.Fatal("small upload expanded without limit",err)}
}
type faultReader struct{failure error}
func(r faultReader)Read([]byte)(int,error){return 0,r.failure}
type cancelReader struct{reader io.Reader;cancel context.CancelFunc;calls int}
func(r *cancelReader)Read(p []byte)(int,error){r.calls++;if r.calls==2{r.cancel()};if len(p)>1{p=p[:1]};return r.reader.Read(p)}
func TestIntegrityCancellationAndInputFailure(t *testing.T){
 good:=packed("first\nsecond\n");bad:=append([]byte(nil),good...);bad[len(bad)-8]^=0xff
 for _,data:=range [][]byte{bad,good[:len(good)-3]}{rows,err:=ParseGzip(context.Background(),bytes.NewReader(data),1000,1000,100,10);if err==nil||rows!=nil{t.Fatal("corrupt archive published partial results",err)}}
 sentinel:=errors.New("upload read failed");if rows,err:=ParseGzip(context.Background(),faultReader{sentinel},1000,1000,100,10);rows!=nil||!errors.Is(err,sentinel){t.Fatal("source error lost",err)}
 ctx,cancel:=context.WithCancel(context.Background());cancel();source:=&cancelReader{reader:bytes.NewReader(good),cancel:func(){}}
 if rows,err:=ParseGzip(ctx,source,1000,1000,100,10);rows!=nil||!errors.Is(err,context.Canceled)||source.calls!=0{t.Fatal("pre-cancel still read input",err,source.calls)}
 ctx,cancel=context.WithCancel(context.Background());defer cancel();source=&cancelReader{reader:bytes.NewReader(good),cancel:cancel}
 if rows,err:=ParseGzip(ctx,source,1000,1000,100,10);rows!=nil||!errors.Is(err,context.Canceled){t.Fatal("mid-read cancellation lost",err)}
}
func TestInvalidLimitsAndMultistream(t *testing.T){
 ctx:=context.Background();good:=packed("one\n");second:=packed("two");combined:=append(append([]byte(nil),good...),second...)
 rows,err:=ParseGzip(ctx,bytes.NewReader(combined),int64(len(combined)),7,3,2);if err!=nil||len(rows)!=2||string(rows[1])!="two"{t.Fatal("multistream integrity",rows,err)}
 if _,err:=ParseGzip(ctx,bytes.NewReader(combined),int64(len(good)),100,100,10);!errors.Is(err,ErrLimit){t.Fatal("second member escaped compressed budget",err)}
 for _,maximum:=range []int64{0,-1,1048577}{if _,err:=ParseGzip(ctx,bytes.NewReader(good),maximum,100,10,10);err==nil{t.Fatal("invalid maximum")}}
 if _,err:=ParseGzip(nil,bytes.NewReader(good),100,100,10,10);err==nil{t.Fatal("missing context")}
 if _,err:=ParseGzip(ctx,nil,100,100,10,10);err==nil{t.Fatal("missing input")}
}
